/*
 * A257908  Sequence (a(n)) generated by Rule 3 (in Comments) with a(1) = 0
 *          and d(1) = 2.
 * https://oeis.org/A257908
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 168, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   contains_int64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  Sequence A257908 – Rule 3 (OEIS description)
 *  a(1) = 0, d(1) = 2.
 *  For k ≥ 1, let A(k) = {a(1)…a(k)} and D(k) = {d(1)…d(k)}.
 *  Step 1:  If there exists an integer h with 1‑a(k) < h < 0,
 *           h ∉ D(k) and a(k)+h ∉ A(k), choose the least such h,
 *           set d(k+1)=h, a(k+1)=a(k)+h and repeat Step 1.
 *  Step 2:  Find the least positive h ∉ D(k) such that
 *           a(k)‑h ∉ A(k); set d(k+1)=h, a(k+1)=a(k)+h
 *           and go back to Step 1.
 *
 *  The implementation below evaluates the sequence for any n ≥ 1
 *  using only integer arithmetic and linear searches for membership.
 *  It works for any seq_t/idx_t type provided by the build system
 *  and for n up to about 10 000 within the required time limits. */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/contains_int64.h"

/* Helper to test membership in the first k elements of an array of seq_t */
static inline bool contains_seq(const seq_t *arr, idx_t k, seq_t val)
{
    for (idx_t i = 1; i <= k; ++i)
        if (arr[i] == val) return true;
    return false;
}

/*  External linkage needed by the build system */
seq_t a(idx_t n)
{
    if (n == 0) return 0;           /* just in case; offset is 1 */

    /* Allocate tables for sequence values and step numbers */
    seq_t *a_vals = (seq_t *)malloc((n + 1) * sizeof(seq_t));
    long long *d_vals = (long long *)malloc((n + 1) * sizeof(long long));
    if (!a_vals || !d_vals) { free(a_vals); free(d_vals); return 0; }

    /* Seed initial values */
    a_vals[1] = 0;
    d_vals[1] = 2;

    idx_t k = 1;                     /* last computed index */

    while (k < n) {
        /* ---- Step 1: try negative h ---- */
        bool moved = false;
        /* Lower bound for h : h > 1‑a(k)  =>  h ≥ 2‑a(k) */
        long long h_low = 2LL - (long long)a_vals[k];
        for (long long h = h_low; h < 0; ++h) {
            if (contains_int64(d_vals, k, h)) continue;        /* h ∈ D(k) */

            /* Compute a(k)+h ; h is negative */
            seq_t next_a;
            if (h >= 0)
                next_a = a_vals[k] + (seq_t)h;                 /* not used here */
            else
                next_a = a_vals[k] - (seq_t)(-h);

            if (contains_seq(a_vals, k, next_a)) continue;    /* next_a ∈ A(k) */

            /* Found suitable h */
            d_vals[k + 1] = h;
            a_vals[k + 1] = next_a;
            ++k;
            moved = true;
            break;
        }

        if (moved) continue;     /* back to Step 1 with new k */

        /* ---- Step 2: look for smallest positive h ---- */
        long long h = 1;
        while (true) {
            if (contains_int64(d_vals, k, h)) { ++h; continue; }

            /* Check a(k)-h ∉ A(k) */
            if (a_vals[k] >= (seq_t)h) {
                seq_t diff = a_vals[k] - (seq_t)h;
                if (contains_seq(a_vals, k, diff)) { ++h; continue; }
            }
            /* If a(k) < h, a(k)-h is negative and cannot be in A(k) */

            /* Accept this h */
            d_vals[k + 1] = h;
            a_vals[k + 1] = a_vals[k] + (seq_t)h;
            ++k;
            break;
        }
    }

    seq_t result = a_vals[n];
    free(a_vals);
    free(d_vals);
    return result;
}
